def transform(grid):
    """Overlay the two equal-sized binary panels: mark their intersection."""
    h = len(grid)
    if not h:
        return []
    separators = [i for i, row in enumerate(grid)
                  if row and row[0] != 0 and all(value == row[0] for value in row)]
    split = next((i for i in separators
                  if i == h - i - 1 and i > 0), None)
    if split is None:
        raise ValueError("expected a uniform separator between equal-sized panels")
    upper, lower = grid[:split], grid[split + 1:]
    if any(len(row) != len(grid[0]) for row in grid):
        raise ValueError("input grid must be rectangular")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(top, bottom)]
            for top, bottom in zip(upper, lower)]


