def transform(grid):
    """Combine two equal-sized binary panels by intersection, coloring hits 2."""
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("input grid must be rectangular")

    # Locate a uniform nonzero separator between two equal-sized panels.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom) and all(len(x) == w for x in top + bottom):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                        for x, y in zip(top, bottom)]
    for c in range(1, w - 1):
        if all(row[c] != 0 and row[c] == grid[0][c] for row in grid):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(x) == len(y) for x, y in zip(left, right)):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                        for x, y in zip(left, right)]
    raise ValueError("expected a uniform nonzero separator between equal-sized panels")


