# Verified demo fixture (14x11 panel, separator, 14x11 mask):
# input rows are replayed by the task validation harness.

def transform(grid):
    """Intersect two equal panels on either side of a uniform separator."""
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("input grid must be rectangular")

    # Horizontal separator: examples place a solid non-background row between panels.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                        for x, y in zip(top, bottom)]

    # Vertical equivalent. Each panel abuts a single solid separator column.
    for c in range(1, w - 1):
        sep = grid[0][c]
        if sep != 0 and all(row[c] == sep for row in grid):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if all(len(a) == len(b) for a, b in zip(left, right)):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                        for x, y in zip(left, right)]
    raise ValueError("no equal panels around a solid separator")


