def _mirror_index(pos, size=3):
    """Map a coordinate in a 3x3 mirrored tiling back to the source tile."""
    tile, offset = divmod(pos, size)
    return size - 1 - offset if tile % 2 == 0 and tile > 0 or tile == 0 else offset


def transform(grid):
    if len(grid) != 3 or any(len(row) != 3 for row in grid):
        raise ValueError("expected a 3x3 input grid")
    return [
        [grid[_mirror_index(r)][_mirror_index(c)] for c in range(9)]
        for r in range(9)
    ]


