def transform(grid):
    """Color continuation cells of patterned horizontal bars at row edges."""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # These tasks show horizontal motifs made of an alternating lead-in
    # followed by a solid bar. The solid bar is continued rightward in 1 when
    # truncated. It can start at the left edge (bars demos) or after a periodic
    # lead-in (checker/stripe demo and held-out pattern).
    for r, row in enumerate(grid):
        # Find a solid foreground run after a non-bg lead; then any background
        # suffix after it is the continuation region. Restrict to actual rows
        # containing foreground and require a sizeable run/lead structure.
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == w - 1:
            continue

        # A simple bar begins at column zero and continues through the first
        # background gap; the demos indicate only its rightmost trailing gap
        # becomes color 1 (no rows with unrelated centered motifs are touched).
        if row[0] != bg:
            # Background suffix after the final colored cell is filled when
            # the row has an alternating lead-in or a long solid prefix.
            prefix = row[:last + 1]
            alternating = len(prefix) >= 5 and all(prefix[i] != prefix[i-1] for i in range(1, len(prefix)))
            solid_start = last
            while solid_start > 0 and row[solid_start - 1] == row[last]:
                solid_start -= 1
            solid_len = last - solid_start + 1
            has_solid = solid_len >= 2 or all(v == row[0] for v in prefix)
            if alternating or has_solid:
                for c in range(last + 1, w):
                    if row[c] == bg:
                        out[r][c] = 1
    return out

