    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        nz = [c for c, x in enumerate(row) if x != bg]
        if not nz:
            continue
        last = nz[-1]
        if last == w - 1:
            continue
        # A repeated two-cell cadence in the motif (foreground, background)
        # predicts sparse foreground continuation, as in alternating rows.
        if last >= 2 and row[last] != bg and row[last - 1] == bg:
            prior = [c for c in nz if c < last and (last - c) % 2 == 0]
            if prior:
                # Use the final observed two-cell phase; continue it to the edge.
                for c in range(last + 1, w):
                    if (c - last) % 2 == 0 and row[c] == bg:
                        out[r][c] = 1
