        # Horizontal bars/motifs ending in a multi-cell foreground run continue
        # uniformly through their empty suffix.
        run = 0
        c = last
        while c >= 0 and row[c] != bg:
            run += 1
            c -= 1
        if run >= 2:
            for c in range(last + 1, w):
