    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != bg]
        if not marks or marks[-1] == w - 1:
            continue
        start, end = marks[0], marks[-1]
        observed = row[start:end + 1]
        chosen = None
        for period in range(1, min(8, len(observed) // 2) + 1):
            if len(observed) >= 2 * period and all(
                    observed[i] == observed[i % period] for i in range(len(observed))):
                chosen = period
                break
        if chosen is None:
            continue
        motif = observed[:chosen]
        for c in range(end + 1, w):
            if motif[(c - start) % chosen] != bg:
                out[r][c] = 1
    return out

