    # Markers of this color are converted to an 8 directly above, with the
    # marker color at the original position and one cell below.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                if r > 0:
                    out[r - 1][c] = 8
                out[r][c] = 1
                if r + 1 < h:
                    out[r + 1][c] = 1
    return out

from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]
    colors = set(counts) - {background}

    def runs_at_edge(color, vertical):
        runs = []
        if vertical:
            for c in (0, w - 1):
                r = 0
                while r < h:
                    if g[r][c] != color:
                        r += 1
                        continue
                    start = r
                    while r < h and g[r][c] == color:
                        r += 1
                    runs.append((c, start, r))
        else:
            for r in (0, h - 1):
                c = 0
                while c < w:
                    if g[r][c] != color:
                        c += 1
                        continue
                    start = c
                    while c < w and g[r][c] == color:
                        c += 1
                    runs.append((r, start, c))
        return runs

    # Long side rails: sparse markers inside one rail project across matching
    # rows to the opposite rail; marked cells become 4 after their ray is drawn.
    for marker in colors:
        rails = [x for x in runs_at_edge(marker, True) if x[2] - x[1] >= 3]
        left = [x for x in rails if x[0] == 0]
        right = [x for x in rails if x[0] == w - 1]
        if not left or not right:
            continue
        # Select the rail containing sparse non-background, non-marker points.
        for source, target in ((left[0], right[0]), (right[0], left[0])):
            c, lo, hi = source
            tc, tlo, thi = target
            signal_cells = [(r, cc) for r in range(lo, hi)
                            for cc in range(w) if g[r][cc] not in (background, marker)]
            if not signal_cells:
                continue
            signal_colors = {g[r][cc] for r, cc in signal_cells}
            # The sparse color is the signal; preserve support for multiple points.
            signal = Counter(g[r][cc] for r, cc in signal_cells).most_common(1)[0][0]
            active = set()
            for r, cc in signal_cells:
                active.add(r - lo)
                step = 1 if cc > c else -1
                x = c + step
                while x != cc:
                    g[r][x] = signal
                    x += step
                g[r][cc] = 4
            for offset in active:
                r = tlo + offset
                if not (tlo <= r < thi):
                    continue
                step = 1 if tc == 0 else -1
                x = tc + step
                while 0 <= x < w:
                    g[r][x] = signal
                    x += step
            return g

    # Short horizontal boundary motifs project vertically in their rightmost
    # column. A signal point terminates that ray and is marked 4.
    for marker in colors:
        motifs = [x for x in runs_at_edge(marker, False) if x[2] - x[1] == 2]
        if not motifs:
            continue
        signal_candidates = colors - {marker}
        for edge_r, start, end in motifs:
            col = end - 1
            direction = 1 if edge_r == 0 else -1
            r = edge_r + direction
            while 0 <= r < h:
                value = g[r][col]
                if value in signal_candidates:
                    for rr in range(edge_r + direction, r, direction):
                        g[rr][col] = value
                    g[r][col] = 4
                    break
                g[r][col] = next(iter(signal_candidates), background)
                r += direction
        return g
    return g


