def transform(grid):
    """Extend rays inward from colored border bars, stopping at signal cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    border_cells = set()
    for c in range(w):
        if grid[0][c] != bg:
            border_cells.add((0, c))
        if grid[h - 1][c] != bg:
            border_cells.add((h - 1, c))
    for r in range(h):
        if grid[r][0] != bg:
            border_cells.add((r, 0))
        if grid[r][w - 1] != bg:
            border_cells.add((r, w - 1))
    border_colors = {grid[r][c] for r, c in border_cells}
    if not border_colors:
        return out
    # In these tasks the border-bar color is distinct from the interior ray color.
    marker = max(border_colors, key=lambda color: sum(
        grid[r][c] == color for r, c in border_cells))
    signal_colors = {v for row in grid for v in row if v not in (bg, marker)}
    if not signal_colors:
        return out
    signal = max(signal_colors, key=lambda color: counts[color])

    # Find connected marker bars that touch the outer border.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == marker and (r, c) in border_cells}
    bars = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    q.append(p)
        bars.append(comp)

    for comp in bars:
        rs = [r for r, _ in comp]
        cs = [c for _, c in comp]
        vertical_bar = max(rs) - min(rs) > max(cs) - min(cs)
        if vertical_bar:
            # A two-cell boundary pair marks its leading (topmost) ray;
            # longer bars emit a ray from every cell.
            origins = comp
            if len(comp) == 2:
                origins = {(min(rs), next(c for r, c in comp if r == min(rs)))}
            for r, c in origins:
                if c == 0:
                    dr, dc = 0, 1
                elif c == w - 1:
                    dr, dc = 0, -1
                else:
                    continue
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    value = out[rr][cc]
                    if value == signal:
                        out[rr][cc] = 4
                        break
                    if value != bg:
                        break
                    out[rr][cc] = signal
                    rr += dr
                    cc += dc
        else:
            origins = comp
            if len(comp) == 2:
                origins = {(next(r for r, c in comp if c == min(cs)), min(cs))}
            for r, c in origins:
                if r == 0:
                    dr, dc = 1, 0
                elif r == h - 1:
                    dr, dc = -1, 0
                else:
                    continue
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    value = out[rr][cc]
                    if value == signal:
                        out[rr][cc] = 4
                        break
                    if value != bg:
                        break
                    out[rr][cc] = signal
                    rr += dr
                    cc += dc
    return out


