def transform(grid):
    """Restore zeroed cells in a periodic diagonal color field and its frame."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The irregular seed is confined to the upper-left; the remaining field
    # follows a periodic color function of r+c. Infer both period and phases.
    samples = [(r + c, grid[r][c])
               for r in range(min(6, h), h)
               for c in range(3, w)
               if grid[r][c] != 0]
    best = None
    for period in range(1, min(h + w, 20)):
        buckets = [Counter() for _ in range(period)]
        for key, color in samples:
            buckets[key % period][color] += 1
        mapping = [bucket.most_common(1)[0][0] if bucket else None
                   for bucket in buckets]
        errors = sum(mapping[key % period] != color for key, color in samples)
        candidate = (errors, period, mapping)
        if best is None or candidate[:2] < best[:2]:
            best = candidate
        if errors == 0:
            best = candidate
            break

    errors, period, mapping = best
    if errors:
        raise ValueError("Observed field does not establish a consistent period")

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                color = mapping[(r + c) % period]
                if color is None:
                    raise ValueError("Missing periodic phase cannot be inferred")
                out[r][c] = color
    return out


