from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append(comp)
    template = max(comps, key=len)
    color_counts = Counter(v for _, _, v in template)
    anchors = [v for v, n in color_counts.items() if n == 1]
    if not anchors:
        return [row[:] for row in grid]
    anchor_color = anchors[0]
    ar, ac, _ = next(cell for cell in template if cell[2] == anchor_color)
    markers = [comp[0] for comp in comps if len(comp) == 1 and comp is not template]
    out = [row[:] for row in grid]
    for mr, mc, _ in markers:
        dr, dc = mr - ar, mc - ac
        for r, c, value in template:
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = value
    return out


