def transform(grid):
    """Extend vertical marker lines upward, using colors of bars they cross."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find marker columns: a vertical, single-color source below the horizontal bars.
    marker_cols = []
    for c in range(w):
        cells = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        if not cells:
            continue
        # Marker source occupies the bottom of the grid; horizontal bars occur above it.
        bottom_r = max(r for r, _ in cells)
        bottom_color = grid[bottom_r][c]
        if bottom_r >= h - 2 and all(grid[r][c] in (0, bottom_color) for r in range(h - 2, h)):
            if any(grid[r][c] == bottom_color for r in range(h - 2, h)):
                marker_cols.append(c)

    # A bar crosses a marker column when same-colored cells flank its one-cell gap.
    crossings = {c: [] for c in marker_cols}
    for r in range(h):
        for c in marker_cols:
            if grid[r][c] != 0 or c == 0 or c == w - 1:
                continue
            color = grid[r][c - 1]
            if color != 0 and grid[r][c + 1] == color:
                crossings[c].append((r, color))
                out[r][c] = color

    # Each horizontal bar colors the vertical ray from itself upward to the
    # previous (higher) crossing; the nearest bar below determines each span.
    for c, bars in crossings.items():
        bars.sort()
        for i, (r, color) in enumerate(bars):
            upper = bars[i - 1][0] + 1 if i > 0 else 0
            for rr in range(upper, r + 1):
                out[rr][c] = color
    return out

