        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
    for r in range(3, n):
        for c in range(n):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out

