def transform(grid):
    """Repeat the bottom/right panel across regions separated by solid lines."""
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(length, separators):
        out = []
        start = 0
        for k in separators:
            if start < k:
                out.append((start, k))
            start = k + 1
        if start < length:
            out.append((start, length))
        return out

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    out = [row[:] for row in grid]
    # The final panel is the source; separators themselves remain unchanged.
    sr0, sr1 = row_spans[-1]
    sc0, sc1 = col_spans[-1]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1 - r0 != sr1 - sr0 or c1 - c0 != sc1 - sc0:
                continue
            for r in range(r1 - r0):
                for c in range(c1 - c0):
                    out[r0 + r][c0 + c] = grid[sr0 + r][sc0 + c]
    return out

