from collections import Counter


def _runs(values, bg):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == bg:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((i, j, color))
        i = j
    return runs


def _matching_runs(a, b):
    for x in a:
        for y in b:
            if x[2] == y[2] and x[1] - x[0] == y[1] - y[0]:
                return x, y
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    pair = _matching_runs(_runs(grid[0], bg), _runs(grid[-1], bg))
    orientation = "horizontal"
    if pair is None:
        pair = _matching_runs(
            _runs([grid[r][0] for r in range(h)], bg),
            _runs([grid[r][-1] for r in range(h)], bg),
        )
        orientation = "vertical"
    if pair is None:
        raise ValueError("No matching equal-colored opposite-edge bars")

    first, second = pair
    out = [row[:] for row in grid]
    if orientation == "vertical":
        left, right = first, second
        bars = {(r, 0) for r in range(left[0], left[1])}
        bars.update((r, w - 1) for r in range(right[0], right[1]))
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and (r, c) not in bars]
        for r, c, color in markers:
            if left[0] <= r < left[1]:
                # Inward ray from the left marker bar to its aligned marker.
                for cc in range(1, c):
                    out[r][cc] = color
                out[r][c] = 4
                paired_r = right[0] + (r - left[0])
                if 0 <= paired_r < h:
                    for cc in range(w - 1):
                        out[paired_r][cc] = color
            elif right[0] <= r < right[1]:
                # Inward ray from the right marker bar to its aligned marker.
                for cc in range(c + 1, w - 1):
